mapper.select:
SELECT l.log_id AS id, u.username AS operator, l.operation_type AS type, l.target_table AS targetTable, l.operation_result AS result, l.operation_time AS time, CAST(l.detail AS CHAR) AS detail FROM operation_log l LEFT JOIN sys_user u ON l.user_id=u.user_id LEFT JOIN sys_department d ON u.department_id=d.department_id
AND 1=0
AND l.user_id=#{scope.userId} AND u.department_id=#{scope.departmentId}
AND 1=0 AND d.region_code IN #{regionCodeItem}
AND 1=0
ORDER BY l.operation_time DESC LIMIT 10
